#!/usr/bin/env python3
"""Manually verified reference metadata; serialization only, not source discovery."""
from pathlib import Path
import json
W=Path(__file__).resolve().parents[1]
R=[]
def ref(key,typ,author,title,year,url,details,**kw):
    R.append(dict(key=key,type=typ,author=author,title=title,year=str(year),url=url,note='verified',annote=details,**kw))

