# Corrections after reading the actual primary headers, not inferring titles.
for r in R:
    if r['key']=='R_SGA3VIA':
        r['author']='Gabriel, Pierre';r['title']='SGA3, Exposé VI A: Généralités sur les groupes algébriques'
    if r['key']=='R_SGA3XI':
        r['author']='Grothendieck, Alexander';r['title']='SGA3, Exposé XI: Critères de représentabilité. Applications aux sous-groupes de type multiplicatif des schémas en groupes affines'
    if r['key']=='R_FGA236Addendum':
        r['title']='Erratum à l’exposé n°236';r['annote']+=' Numdam catalogue title is Erratum à l’exposé n°236; the body is the FGA complement/commentary.'
    if r['key']=='R_Suzuki2023':
        r['title']='Finite generation of nilpotent quotients of fundamental groups of punctured spectra'
    if r['key']=='R_ChowKodaira1952':
        r['note']='unverified';r['annote']='Real reference and historical comparison checked in the primary Kodaira1960 article, but direct full-source access was not completed: DOI/PMC route met an access challenge. The1952 Kähler hypothesis is reported through the checked1960 comparison. The underlying1952 theorem was not independently reread.'

out=W/'parts/root'
(out/'reference_details.json').write_text(json.dumps(R,ensure_ascii=False,indent=2)+'\n')
chunks=[]
for x in R:
    fields={k:v for k,v in x.items() if k not in ('key','type')}
    chunks.append('@'+x['type']+'{'+x['key']+',\n'+',\n'.join('  '+k+' = {'+str(v).replace('{','').replace('}','')+'}' for k,v in fields.items())+'\n}')
(out/'references.bib').write_text('\n\n'.join(chunks)+'\n')
print(json.dumps({'references':len(R),'all_metadata_manually_entered':True,'note_meaning':'opened URL, with proof/metadata limits in annote'},indent=2))
